using System.IdentityModel.Tokens.Jwt;using MediDesk.Api.Authorization;using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Administration;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace MediDesk.Api.Controllers{[ApiController][Route("api/settings")][Authorize(Policy=PermissionPolicies.SettingsView)]public sealed class SettingsController(ISettingsService s):ControllerBase{[HttpGet]public Task<IReadOnlyCollection<AppSettingDto>>Get(CancellationToken ct)=>s.GetAsync(ct);[HttpPut][Authorize(Policy=PermissionPolicies.SettingsEdit)]public Task<IReadOnlyCollection<AppSettingDto>>Put(UpdateSettingsRequest r,CancellationToken ct)=>s.UpdateAsync(r.Values,long.Parse(User.FindFirst(JwtRegisteredClaimNames.Sub)!.Value),ct);}}

